// HasApprovedByAccount applies the HasEdge predicate on the "approved_by_account" edge.
func HasApprovedByAccount() predicate.OAuthRegistrationApproval {
	return predicate.OAuthRegistrationApproval(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ApprovedByAccountTable, ApprovedByAccountColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasApprovedByAccountWith applies the HasEdge predicate on the "approved_by_account" edge with a given conditions (other predicates).
func HasApprovedByAccountWith(preds ...predicate.Account) predicate.OAuthRegistrationApproval {
	return predicate.OAuthRegistrationApproval(func(s *sql.Selector) {
		step := newApprovedByAccountStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OAuthRegistrationApproval) predicate.OAuthRegistrationApproval {
	return predicate.OAuthRegistrationApproval(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OAuthRegistrationApproval) predicate.OAuthRegistrationApproval {
	return predicate.OAuthRegistrationApproval(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OAuthRegistrationApproval) predicate.OAuthRegistrationApproval {
	return predicate.OAuthRegistrationApproval(sql.NotPredicates(p))
}
